import{_ as t,o as r,c as e,Q as n}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"Module 3: When Things Go Wrong","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/modules/maltese-module3-analysis.md","filePath":"en/more/maltese/modules/maltese-module3-analysis.md"}'),o={name:"en/more/maltese/modules/maltese-module3-analysis.md"},a=n('<h1 id="module-3-when-things-go-wrong" tabindex="-1">Module 3: When Things Go Wrong <a class="header-anchor" href="#module-3-when-things-go-wrong" aria-label="Permalink to &quot;Module 3: When Things Go Wrong&quot;">​</a></h1><p><strong>Module title: Meta l-affarijiet ma jmorrux kif nixtiequ</strong><br><strong>English title: When things go wrong</strong></p><h2 id="module-title-breakdown" tabindex="-1">Module Title Breakdown <a class="header-anchor" href="#module-title-breakdown" aria-label="Permalink to &quot;Module Title Breakdown&quot;">​</a></h2><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Meta l-affarijiet ma jmorrux kif nixtiequ</td><td>When things don&#39;t go as we wish</td><td><strong>Meta</strong> when<br><strong>l-affarijiet</strong> things (article l- + affarijiet)<br><strong>ma jmorrux</strong> they don&#39;t go well (ma … -x forms the negative; positive form jmorru, literally &quot;they go&quot;)<br><strong>kif</strong> as, the way<br><strong>nixtiequ</strong> we wish, we want (first person plural).</td></tr></tbody></table><p>The English title <strong>When things go wrong</strong> is close to &quot;when things go wrong&quot;; the Maltese title reads more literally as &quot;when things don&#39;t go as we wish&quot;. This module practises expressing yourself when things go wrong, through situations such as losing things, being late, accidents, and service complaints.</p><h2 id="overall-outline" tabindex="-1">Overall Outline <a class="header-anchor" href="#overall-outline" aria-label="Permalink to &quot;Overall Outline&quot;">​</a></h2><table><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td>1–2</td><td>Two everyday dialogues: looking for a lost ring, asking for help when late; comprehension questions</td></tr><tr><td>3–5</td><td>Spoken situational expressions, restaurant complaint review, written complaint letter</td></tr><tr><td>6–11</td><td>Noun singular and plural; plural formation types; identifying plural nouns in sentences</td></tr><tr><td>12–15</td><td>Prepositions of place; describing object positions from pictures and practising noun plurals</td></tr></tbody></table><h3 id="reading-notes" tabindex="-1">Reading Notes <a class="header-anchor" href="#reading-notes" aria-label="Permalink to &quot;Reading Notes&quot;">​</a></h3><ul><li><strong>il-/l-</strong> definite article, similar to English <em>the</em>; in context it can be translated &quot;this/that&quot; or left untranslated.</li><li><strong>fil-</strong> in the (preposition + article, written together).</li><li><strong>tal-</strong> of the (preposition + article, written together).</li><li><strong>bil-</strong> with/by the (preposition + article, written together).</li><li><strong>plural sħiħ</strong> regular/full plural, usually formed by adding an ending.</li><li><strong>plural miksur</strong> broken plural; the stem changes internally and cannot be derived by a single uniform rule.</li></ul><h2 id="_1-two-dialogues" tabindex="-1">1 Two Dialogues <a class="header-anchor" href="#_1-two-dialogues" aria-label="Permalink to &quot;1 Two Dialogues&quot;">​</a></h2><h3 id="dialogue-one-brenda-can-t-find-her-ring" tabindex="-1">Dialogue One: Brenda Can&#39;t Find Her Ring <a class="header-anchor" href="#dialogue-one-brenda-can-t-find-her-ring" aria-label="Permalink to &quot;Dialogue One: Brenda Can&#39;t Find Her Ring&quot;">​</a></h3><p><strong>Qari — Aqra dawn id-djalogi.</strong> (Reading — read these dialogues.)</p><ul><li><strong>qari</strong> reading.</li><li><strong>aqra</strong> read (imperative).</li><li><strong>dawn</strong> these.</li><li><strong>id-djalogi</strong> the dialogues (plural).</li></ul><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Xi ġralek, Brenda?</td><td>What happened to you, Brenda?</td><td><strong>xi</strong> what<br><strong>ġralek</strong> happened to you (ġara + le-k)<br><strong>Brenda</strong> a name.</td></tr><tr><td>Ħaw’, Anna, tlift iċ-ċurkett!</td><td>Hi, Anna, I lost the ring!</td><td><strong>Ħaw’</strong> hi<br><strong>tlift</strong> I lost<br><strong>iċ-ċurkett</strong> the ring (article + ring).</td></tr><tr><td>Fejn kont l-aħħar?</td><td>Where were you the last time (you remember)?</td><td><strong>fejn</strong> where<br><strong>kont</strong> you were<br><strong>l-aħħar</strong> last.</td></tr><tr><td>Ilni ġurnata ndur il-ħwienet!</td><td>I&#39;ve been going around the shops all day!</td><td><strong>ilni</strong> I have been … for this long<br><strong>ġurnata</strong> a day<br><strong>ndur</strong> I go around<br><strong>il-ħwienet</strong> the shops (plural).</td></tr><tr><td>Ma nafx meta kien l-aħħar f’subgħi!</td><td>I don&#39;t know when it was last on my finger!</td><td><strong>ma … x</strong> negative frame<br><strong>nafx</strong> I don&#39;t know<br><strong>meta</strong> when<br><strong>kien</strong> it was<br><strong>l-aħħar</strong> the last time<br><strong>f’</strong> on/in<br><strong>subgħi</strong> my finger.</td></tr><tr><td>Ikkalma. Prova aħseb ftit.</td><td>Calm down. Try to think a little.</td><td><strong>ikkalma</strong> calm down (imperative)<br><strong>prova</strong> try<br><strong>aħseb</strong> think<br><strong>ftit</strong> a little.</td></tr><tr><td>Iva! Sakemm xtrajt il-libsa kien għadu f’subgħajja għax jien u nippruvaha weħilli magħha.</td><td>Yes! When I bought the dress it was still on my finger, because while I was trying it on it got caught on the dress.</td><td><strong>iva</strong> yes<br><strong>sakemm</strong> by the time / when<br><strong>xtrajt</strong> I bought<br><strong>il-libsa</strong> the dress<br><strong>kien għadu</strong> it was still<br><strong>f’</strong> on<br><strong>subgħajja</strong> my fingers<br><strong>għax</strong> because<br><strong>jien u nippruvaha</strong> while I was trying it on<br><strong>weħilli</strong> it stuck to me<br><strong>magħha</strong> on it/with it (referring to the dress).</td></tr><tr><td>Mela ejja mmorru f’dak il-ħanut, forsi waqagħlek hemm.</td><td>Well then let&#39;s go to that shop; maybe it fell off there.</td><td><strong>mela</strong> so, then<br><strong>ejja</strong> come on<br><strong>mmorru</strong> we go<br><strong>f’dak</strong> in that<br><strong>il-ħanut</strong> the shop<br><strong>forsi</strong> maybe<br><strong>waqagħlek</strong> it fell off you<br><strong>hemm</strong> there.</td></tr><tr><td>Nispera li jekk sabu xi ħadd, ma baqax sejjer bih!</td><td>I hope that if someone found it, they didn&#39;t go off with it!</td><td><strong>nispera</strong> I hope<br><strong>li</strong> that<br><strong>jekk</strong> if<br><strong>sabu</strong> he found it (sab + object suffix -u; the subject is the following xi ħadd, not &quot;they&quot;)<br><strong>xi ħadd</strong> someone<br><strong>ma … x</strong> negative<br><strong>baqax</strong> didn&#39;t continue<br><strong>sejjer</strong> going<br><strong>bih</strong> with it.</td></tr></tbody></table><h3 id="dialogue-two-emily-misses-the-bus" tabindex="-1">Dialogue Two: Emily Misses the Bus <a class="header-anchor" href="#dialogue-two-emily-misses-the-bus" aria-label="Permalink to &quot;Dialogue Two: Emily Misses the Bus&quot;">​</a></h3><p>The sentences about being late and waiting for the next bus have been completed according to your corrected transcript.</p><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Ħelow, is-Sur Caruana?</td><td>Hello, is that Mr Caruana?</td><td><strong>Ħelow</strong> hello<br><strong>is-Sur</strong> Mr<br><strong>Caruana</strong> a surname.</td></tr><tr><td>Iva, jien hu, għidli.</td><td>Yes, it&#39;s me, go ahead.</td><td><strong>iva</strong> yes<br><strong>jien</strong> I<br><strong>hu</strong> he/it&#39;s me (the person on the phone)<br><strong>għidli</strong> tell me / go ahead.</td></tr><tr><td>Sur Caruana, jien Emily. Skużani imma ħa nasal tard għax-xogħol għax tlift tal-linja bl-eżatt!</td><td>Mr Caruana, this is Emily. I&#39;m sorry but I&#39;m going to be late for work because I just missed the bus!</td><td><strong>Sur Caruana</strong> Mr Caruana<br><strong>jien</strong> I (the &quot;am&quot; is omitted)<br><strong>Emily</strong> a name<br><strong>Skużani</strong> excuse me / I&#39;m sorry<br><strong>imma</strong> but<br><strong>ħa nasal</strong> I will arrive (ħa marks the future, nasal &quot;I arrive&quot;)<br><strong>tard</strong> late<br><strong>għax-xogħol</strong> to work (contraction of għal + article + xogħol; not &quot;because&quot; here)<br><strong>għax</strong> because<br><strong>tlift</strong> I missed<br><strong>tal-linja</strong> the bus (karozza omitted; the full expression is karozza tal-linja)<br><strong>bl-eżatt</strong> exactly, just.</td></tr><tr><td>Issa fadal nofs siegħa oħra sabiex tgħaddi oħra.</td><td>Now there&#39;s still half an hour before another bus comes by.</td><td><strong>Issa</strong> now<br><strong>fadal</strong> there remains<br><strong>nofs siegħa</strong> half an hour (nofs: half; siegħa: hour)<br><strong>oħra</strong> another, additional (modifying siegħa; nofs siegħa oħra together means &quot;another half hour&quot;)<br><strong>sabiex</strong> so that; in this waiting context, &quot;before&quot;<br><strong>tgħaddi</strong> it passes (third person feminine singular, referring to the bus)<br><strong>oħra</strong> another one (feminine singular, noun omitted).</td></tr><tr><td>Żgur ma tistax tagħmel mod ieħor? Forsi jista’ jwasslek xi ħadd?</td><td>Surely you can&#39;t do it any other way? Maybe someone can give you a lift?</td><td><strong>żgur</strong> surely<br><strong>ma tistax</strong> you cannot<br><strong>tagħmel</strong> do<br><strong>mod ieħor</strong> another way<br><strong>forsi</strong> maybe<br><strong>jista’</strong> can<br><strong>jwasslek</strong> take you<br><strong>xi ħadd</strong> someone.</td></tr><tr><td>Ħadd ma jista’ jwassalni bħalissa għax il-papà għandu l-karozza bil-ħsara.</td><td>No one can take me right now because Dad&#39;s car is broken.</td><td><strong>ħadd</strong> no one<br><strong>ma jista’</strong> cannot<br><strong>jwassalni</strong> take me<br><strong>bħalissa</strong> right now<br><strong>għax</strong> because<br><strong>il-papà</strong> dad<br><strong>għandu</strong> he has<br><strong>il-karozza</strong> the car<br><strong>bil-ħsara</strong> damaged/broken.</td></tr><tr><td>Jekk naqbad taxi tiġini ftit għolja.</td><td>If I take a taxi it will cost me a bit more.</td><td><strong>jekk</strong> if<br><strong>naqbad</strong> I take<br><strong>taxi</strong> taxi<br><strong>tiġini</strong> it will cost me<br><strong>ftit</strong> a bit<br><strong>għolja</strong> expensive (literally &quot;high&quot;).</td></tr><tr><td>Inti fejn qiegħda?</td><td>Where are you? (said to a woman)</td><td><strong>inti</strong> you<br><strong>fejn</strong> where<br><strong>qiegħda</strong> located/staying (feminine form).</td></tr><tr><td>Ħa nara jekk il-ħaddiema humiex qrib tiegħek bil-vann tax-xogħol. Fil-każ jgħaddu għalik huma.</td><td>Let me see if the workers are near you with the work van. If so, they&#39;ll come by for you.</td><td><strong>ħa nara</strong> let me see<br><strong>jekk</strong> whether<br><strong>il-ħaddiema</strong> the workers<br><strong>humiex</strong> whether they are<br><strong>qrib</strong> near<br><strong>tiegħek</strong> yours<br><strong>bil-vann</strong> with/by van<br><strong>tax-xogħol</strong> work<br><strong>fil-każ</strong> in that case<br><strong>jgħaddu</strong> they pass by<br><strong>għalik</strong> for you<br><strong>huma</strong> they.</td></tr><tr><td>Jien qiegħda ż-Żurrieq, fil-pjazza.</td><td>I&#39;m in Żurrieq, at the square.</td><td><strong>jien</strong> I<br><strong>qiegħda</strong> located (female speaker)<br><strong>ż-Żurrieq</strong> the place name Żurrieq<br><strong>fil-pjazza</strong> at the square.</td></tr><tr><td>Ok, se niċċekkja u nerġa’ nċempillek.</td><td>OK, I&#39;ll check and call you back.</td><td><strong>se</strong> will<br><strong>niċċekkja</strong> I check<br><strong>u</strong> and<br><strong>nerġa’</strong> again<br><strong>nċempillek</strong> I call you.</td></tr><tr><td>Illaħwa, kieku tajjeb! Grazzi, Sur Caruana, u skużani mill-ġdid.</td><td>Oh, that would be great! Thank you, Mr Caruana, and I&#39;m sorry again.</td><td><strong>illaħwa</strong> oh dear/wow (exclamation)<br><strong>kieku</strong> if that were so<br><strong>tajjeb</strong> good<br><strong>grazzi</strong> thank you<br><strong>u</strong> and<br><strong>skużani</strong> excuse me<br><strong>mill-ġdid</strong> again.</td></tr></tbody></table><hr><h2 id="_2-dialogue-comprehension-questions" tabindex="-1">2 Dialogue Comprehension Questions <a class="header-anchor" href="#_2-dialogue-comprehension-questions" aria-label="Permalink to &quot;2 Dialogue Comprehension Questions&quot;">​</a></h2><p><strong>Wieġeb dawn il-mistoqsijiet dwar l-ewwel djalogu.</strong> (Answer these questions about the first dialogue.)</p><table><thead><tr><th>Question</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Min huma l-karattri ta’ dan id-djalogu?</td><td>Who are the characters in this dialogue?<br><strong>min</strong> who<br><strong>huma</strong> are<br><strong>il-karattri</strong> the characters<br><strong>ta’ dan</strong> of this<br><strong>id-djalogu</strong> the dialogue.<br>Reference answer: Brenda and Anna.</td></tr><tr><td>X’inhi l-problema?</td><td>What is the problem?<br><strong>x’inhi</strong> what is (feminine)<br><strong>il-problema</strong> the problem.<br>Reference answer: Brenda lost her ring.</td></tr><tr><td>Brenda fejn qed taħseb li tilfitu ċ-ċurkett?</td><td>Where does Brenda think she lost the ring?<br><strong>fejn</strong> where<br><strong>qed taħseb</strong> is thinking<br><strong>li</strong> that<br><strong>tilfitu</strong> lost it<br><strong>iċ-ċurkett</strong> the ring.<br>Reference answer: possibly in the shop where she bought the dress.</td></tr><tr><td>X’qed tispera Brenda?</td><td>What is Brenda hoping?<br><strong>x’</strong> what<br><strong>qed</strong> -ing<br><strong>tispera</strong> she hopes.<br>Reference answer: that whoever found the ring did not take it away.</td></tr></tbody></table><p><strong>Wieġeb dawn il-mistoqsijiet dwar it-tieni djalogu.</strong> (Answer these questions about the second dialogue.)</p><table><thead><tr><th>Question</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Min huma l-karattri ta’ dan id-djalogu?</td><td>Who are the characters in this dialogue? Reference answer: Emily and Mr Caruana.</td></tr><tr><td>X’inhi l-problema?</td><td>What is the problem? Reference answer: Emily missed the bus and is about to be late; her dad&#39;s car is also broken.</td></tr><tr><td>Lil min ċemplet Emily?</td><td>Who did Emily call?<br><strong>lil min</strong> whom<br><strong>ċemplet</strong> she called.<br>Reference answer: Mr Caruana.</td></tr><tr><td>Fejn qed tistenna Emily?</td><td>Where is Emily waiting?<br><strong>fejn</strong> where<br><strong>qed tistenna</strong> is waiting<br><strong>Emily</strong> a name.<br>Reference answer: at the square in Żurrieq.</td></tr></tbody></table><h3 id="full-reference-answers-to-the-eight-questions-in-maltese" tabindex="-1">Full Reference Answers to the Eight Questions in Maltese <a class="header-anchor" href="#full-reference-answers-to-the-eight-questions-in-maltese" aria-label="Permalink to &quot;Full Reference Answers to the Eight Questions in Maltese&quot;">​</a></h3><table><thead><tr><th>No.</th><th>Reference answer and word-by-word breakdown</th></tr></thead><tbody><tr><td>1</td><td><strong>Il-karattri huma Brenda u Anna.</strong> The characters are Brenda and Anna.<br><strong>il-karattri</strong> the characters<br><strong>huma</strong> are<br><strong>Brenda</strong> a name<br><strong>u</strong> and<br><strong>Anna</strong> a name.</td></tr><tr><td>2</td><td><strong>Brenda tilfet iċ-ċurkett.</strong> Brenda lost the ring.<br><strong>Brenda</strong> a name<br><strong>tilfet</strong> she lost<br><strong>iċ-ċurkett</strong> the ring.</td></tr><tr><td>3</td><td><strong>Brenda taħseb li tilfet iċ-ċurkett fil-ħanut fejn xtrat il-libsa.</strong> Brenda thinks she lost the ring in the shop where she bought the dress.<br><strong>Brenda</strong> a name<br><strong>taħseb</strong> she thinks<br><strong>li</strong> introduces the clause<br><strong>tilfet</strong> she lost<br><strong>iċ-ċurkett</strong> the ring<br><strong>fil-ħanut</strong> in the shop<br><strong>fejn</strong> where<br><strong>xtrat</strong> she bought<br><strong>il-libsa</strong> the dress.</td></tr><tr><td>4</td><td><strong>Brenda tispera li min sab iċ-ċurkett ma ħadux miegħu.</strong> Brenda hopes that whoever found the ring didn&#39;t take it with him.<br><strong>Brenda</strong> a name<br><strong>tispera</strong> she hopes<br><strong>li</strong> introduces the clause<br><strong>min</strong> the one who<br><strong>sab</strong> he found<br><strong>iċ-ċurkett</strong> the ring<br><strong>ma ħadux</strong> he didn&#39;t take it (negative + object suffix)<br><strong>miegħu</strong> with him.</td></tr><tr><td>5</td><td><strong>Il-karattri huma Emily u s-Sur Caruana.</strong> The characters are Emily and Mr Caruana.<br><strong>il-karattri</strong> the characters<br><strong>huma</strong> are<br><strong>Emily</strong> a name<br><strong>u</strong> and<br><strong>s-Sur Caruana</strong> Mr Caruana.</td></tr><tr><td>6</td><td><strong>Emily tilfet tal-linja u se tasal tard għax-xogħol.</strong> Emily missed the bus and will arrive late for work.<br><strong>Emily</strong> a name<br><strong>tilfet</strong> she missed<br><strong>tal-linja</strong> the bus (karozza omitted)<br><strong>u</strong> and<br><strong>se</strong> will<br><strong>tasal</strong> she arrives<br><strong>tard</strong> late<br><strong>għax-xogħol</strong> to work.</td></tr><tr><td>7</td><td><strong>Emily ċemplet lis-Sur Caruana.</strong> Emily called Mr Caruana.<br><strong>Emily</strong> a name<br><strong>ċemplet</strong> she called<br><strong>lis-Sur Caruana</strong> to Mr Caruana.</td></tr><tr><td>8</td><td><strong>Emily qed tistenna fil-pjazza taż-Żurrieq.</strong> Emily is waiting in Żurrieq square.<br><strong>Emily</strong> a name<br><strong>qed</strong> -ing<br><strong>tistenna</strong> she waits<br><strong>fil-pjazza</strong> in the square<br><strong>taż-Żurrieq</strong> of Żurrieq.</td></tr></tbody></table><p>Shared words used by both question sets:</p><ul><li><strong>wieġeb</strong> answer.</li><li><strong>dawn il-mistoqsijiet</strong> these questions.</li><li><strong>dwar</strong> about.</li><li><strong>l-ewwel djalogu</strong> the first dialogue.</li><li><strong>it-tieni djalogu</strong> the second dialogue.</li></ul><hr><h2 id="_3-picture-based-speaking" tabindex="-1">3 Picture-Based Speaking <a class="header-anchor" href="#_3-picture-based-speaking" aria-label="Permalink to &quot;3 Picture-Based Speaking&quot;">​</a></h2><p><strong>It-Taħdit — X’ġara f’dawn l-istampi?</strong> (Speaking — what happened in these pictures?)</p><h3 id="traffic-accident-collision" tabindex="-1">Traffic Accident / Collision <a class="header-anchor" href="#traffic-accident-collision" aria-label="Permalink to &quot;Traffic Accident / Collision&quot;">​</a></h3><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Skużani ħafna!</td><td>I&#39;m very sorry!</td><td><strong>skużani</strong> excuse me<br><strong>ħafna</strong> very.</td></tr><tr><td>Ma rajtekx… ma ndunajtx bik… kont aljenat/a.</td><td>I didn&#39;t see you… I didn&#39;t notice you… I was distracted.</td><td><strong>ma … x</strong> not<br><strong>rajtek</strong> I saw you<br><strong>ndunajtx</strong> I didn&#39;t notice<br><strong>bik</strong> you<br><strong>kont</strong> I was<br><strong>aljenat/a</strong> distracted (m/f).</td></tr><tr><td>Tort tiegħek! Suppost inti waqaft!</td><td>It&#39;s your fault! You were supposed to stop!</td><td><strong>tort</strong> fault<br><strong>tiegħek</strong> yours<br><strong>suppost</strong> supposed to<br><strong>inti</strong> you<br><strong>waqaft</strong> you stopped.</td></tr><tr><td>Għandek raġun, mhux apposta!</td><td>You&#39;re right, it wasn&#39;t on purpose!</td><td><strong>għandek raġun</strong> you&#39;re right<br><strong>mhux</strong> not<br><strong>apposta</strong> on purpose.</td></tr><tr><td>X’qatgħa ħadt!</td><td>What a fright I got!</td><td><strong>x’qatgħa</strong> what a shock<br><strong>ħadt</strong> I got (this form can also mean &quot;you got&quot;; distinguish by context).</td></tr><tr><td>Weġġajt?</td><td>Are you hurt?</td><td><strong>weġġajt</strong> you got hurt.</td></tr><tr><td>Ħa nċempel għall-ambulanza.</td><td>I&#39;ll call an ambulance.</td><td><strong>ħa</strong> will/let me<br><strong>nċempel</strong> I call<br><strong>għall-</strong> for<br><strong>ambulanza</strong> ambulance.</td></tr><tr><td>Ħa nċempel għall-warden.</td><td>I&#39;ll call the traffic warden/officer.</td><td><strong>ħa nċempel</strong> I&#39;ll call<br><strong>għall-warden</strong> for the warden (a loanword used for the officer on site).</td></tr><tr><td>Xi ħadd jista’ jgħinna?</td><td>Can someone help us?</td><td><strong>xi ħadd</strong> someone<br><strong>jista’</strong> can<br><strong>jgħinna</strong> help us.</td></tr><tr><td>Tiċċaqlaqx!</td><td>Don&#39;t move!</td><td><strong>tiċċaqlaq</strong> move<br><strong>-x</strong> negative imperative.</td></tr></tbody></table><h3 id="asking-about-products-in-a-shop" tabindex="-1">Asking About Products in a Shop <a class="header-anchor" href="#asking-about-products-in-a-shop" aria-label="Permalink to &quot;Asking About Products in a Shop&quot;">​</a></h3><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Fejn hu…?</td><td>Where is …?</td><td><strong>fejn</strong> where<br><strong>hu</strong> it is (masculine noun).</td></tr><tr><td>Qed infittex … ma nistax insibu.</td><td>I&#39;m looking for … I can&#39;t find it.</td><td><strong>qed infittex</strong> looking for<br><strong>ma nistax</strong> I can&#39;t<br><strong>insibu</strong> find it.</td></tr><tr><td>Taf fejn nista’ nsib…?</td><td>Do you know where I can find …?</td><td><strong>taf</strong> you know<br><strong>fejn</strong> where<br><strong>nista’</strong> I can<br><strong>nsib</strong> find.</td></tr><tr><td>Għandkom / Għandek…?</td><td>Do you have …? (you-plural / you-singular)</td><td><strong>għandkom</strong> you have (plural)<br><strong>għandek</strong> you have (singular).</td></tr><tr><td>Liema naħa qiegħed il-laħam?</td><td>Which side is the meat on?</td><td><strong>liema</strong> which<br><strong>naħa</strong> side/direction<br><strong>qiegħed</strong> is located<br><strong>il-laħam</strong> the meat.</td></tr><tr><td>Kemm hu dan il-prodott? Kemm jiswa?</td><td>How much is this product? How much does it cost?</td><td><strong>kemm</strong> how much<br><strong>hu</strong> is<br><strong>dan</strong> this<br><strong>il-prodott</strong> the product<br><strong>jiswa</strong> it costs.</td></tr><tr><td>Hawn xi offerti?</td><td>Are there any offers here?</td><td><strong>hawn</strong> here there are<br><strong>xi</strong> some/any<br><strong>offerti</strong> offers, specials.</td></tr></tbody></table><h3 id="complaining-at-a-restaurant" tabindex="-1">Complaining at a Restaurant <a class="header-anchor" href="#complaining-at-a-restaurant" aria-label="Permalink to &quot;Complaining at a Restaurant&quot;">​</a></h3><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Wejter! Dan l-ikel mhux tajjeb!</td><td>Waiter! This food isn&#39;t good!</td><td><strong>wejter</strong> waiter<br><strong>dan</strong> this<br><strong>l-ikel</strong> the food<br><strong>mhux tajjeb</strong> not good.</td></tr><tr><td>Dan l-ikel kiesaħ!</td><td>This food is cold!</td><td><strong>dan</strong> this<br><strong>l-ikel</strong> food<br><strong>kiesaħ</strong> cold.</td></tr><tr><td>Dan il-laħam misjur ħafna u iebes.</td><td>This meat is overcooked and tough.</td><td><strong>dan</strong> this<br><strong>il-laħam</strong> the meat<br><strong>misjur</strong> well done/overcooked<br><strong>ħafna</strong> very, too<br><strong>u</strong> and<br><strong>iebes</strong> hard, tough.</td></tr><tr><td>Din it-tiġieġa għadha roża, bid-demm.</td><td>This chicken is still pink, with blood.</td><td><strong>din</strong> this (feminine)<br><strong>it-tiġieġa</strong> the chicken<br><strong>għadha</strong> still<br><strong>roża</strong> pink<br><strong>bid-demm</strong> with blood.</td></tr><tr><td>Jien mhux dan il-platt ordnajt.</td><td>I didn&#39;t order this dish.</td><td><strong>jien</strong> I<br><strong>mhux</strong> not<br><strong>dan il-platt</strong> this dish<br><strong>ordnajt</strong> I ordered.</td></tr><tr><td>Dan l-ikel mielaħ ħafna.</td><td>This food is too salty.</td><td><strong>mielaħ</strong> salty<br><strong>ħafna</strong> very, too.</td></tr><tr><td>Dan żgur ma fihx dqiq / ħalib?</td><td>This surely doesn&#39;t contain flour/milk, right?</td><td><strong>dan</strong> this<br><strong>żgur</strong> surely<br><strong>ma fihx</strong> doesn&#39;t contain<br><strong>dqiq</strong> flour<br><strong>ħalib</strong> milk.</td></tr><tr><td>Nixtieq inkellem lill-maniġer jekk ma jimpurtax.</td><td>I&#39;d like to speak to the manager if you don&#39;t mind.</td><td><strong>nixtieq</strong> I&#39;d like<br><strong>inkellem</strong> I speak to<br><strong>lill-maniġer</strong> the manager<br><strong>jekk</strong> if<br><strong>ma jimpurtax</strong> it doesn&#39;t matter.</td></tr></tbody></table><hr><h2 id="_4-situational-dialogues-and-restaurant-reviews" tabindex="-1">4 Situational Dialogues and Restaurant Reviews <a class="header-anchor" href="#_4-situational-dialogues-and-restaurant-reviews" aria-label="Permalink to &quot;4 Situational Dialogues and Restaurant Reviews&quot;">​</a></h2><p><strong>Agħżel xenarju minn dawn it-tlieta u pprepara djalogu li ser tippreżenta quddiem sħabek.</strong></p><p>Choose one of the three scenarios and prepare a dialogue to present in front of your classmates.</p><ul><li><strong>agħżel</strong> choose</li><li><strong>xenarju</strong> scenario</li><li><strong>minn</strong> from</li><li><strong>dawn it-tlieta</strong> these three</li><li><strong>u</strong> and</li><li><strong>pprepara</strong> prepare</li><li><strong>djalogu</strong> dialogue</li><li><strong>li ser</strong> that will</li><li><strong>tippreżenta</strong> you present</li><li><strong>quddiem</strong> in front of</li><li><strong>sħabek</strong> your classmates.</li></ul><h3 id="reference-dialogue-answers-restaurant" tabindex="-1">Reference Dialogue Answers (Restaurant) <a class="header-anchor" href="#reference-dialogue-answers-restaurant" aria-label="Permalink to &quot;Reference Dialogue Answers (Restaurant)&quot;">​</a></h3><table><thead><tr><th>Completed line</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Klijent: Skużani, dan l-ikel kiesaħ.</td><td>Customer: Excuse me, this food is cold.<br><strong>klijent</strong> customer<br><strong>skużani</strong> excuse me<br><strong>dan</strong> this<br><strong>l-ikel</strong> the food<br><strong>kiesaħ</strong> cold.</td></tr><tr><td>Wejter: Jiddispjaċini. Trid platt ieħor?</td><td>Waiter: I&#39;m sorry. Would you like another plate?<br><strong>wejter</strong> waiter<br><strong>jiddispjaċini</strong> I&#39;m sorry<br><strong>trid</strong> you want<br><strong>platt</strong> a plate/dish<br><strong>ieħor</strong> another.</td></tr><tr><td>Klijent: Iva, jekk jogħġbok.</td><td>Customer: Yes, please.<br><strong>iva</strong> yes<br><strong>jekk jogħġbok</strong> please.</td></tr><tr><td>Wejter: Se nġiblek platt sħun minnufih.</td><td>Waiter: I&#39;ll bring you a hot plate right away.<br><strong>se</strong> will<br><strong>nġiblek</strong> I bring you<br><strong>platt</strong> a plate<br><strong>sħun</strong> hot<br><strong>minnufih</strong> immediately.</td></tr></tbody></table><p><strong>Il-Qari — Aqra dan l-ilment u l-kummenti daqslikieku rajthom fuq il-midja soċjali.</strong></p><p>Read this complaint and the comments as if you had seen them on social media.</p><ul><li><strong>aqra</strong> read</li><li><strong>dan l-ilment</strong> this complaint</li><li><strong>u</strong> and</li><li><strong>il-kummenti</strong> the comments</li><li><strong>daqslikieku</strong> as if</li><li><strong>rajthom</strong> you saw them</li><li><strong>fuq</strong> on</li><li><strong>il-midja soċjali</strong> social media.</li></ul><h3 id="rachel-s-review" tabindex="-1">Rachel&#39;s Review <a class="header-anchor" href="#rachel-s-review" aria-label="Permalink to &quot;Rachel&#39;s Review&quot;">​</a></h3><blockquote><p><strong>Ma nirrakkomandax ir-ristorant &quot;Bella Malta&quot; li jinsab Marsaxlokk minħabba s-servizz ħażin li rċivejna!</strong></p><p>I don&#39;t recommend the &quot;Bella Malta&quot; restaurant in Marsaxlokk because of the bad service we received!</p><ul><li><strong>ma nirrakkomandax</strong> I don&#39;t recommend</li><li><strong>ir-ristorant</strong> the restaurant</li><li><strong>li</strong> that</li><li><strong>jinsab</strong> is located</li><li><strong>minħabba</strong> because of</li><li><strong>is-servizz</strong> the service</li><li><strong>ħażin</strong> bad</li><li><strong>rċivejna</strong> we received.</li></ul></blockquote><blockquote><p><strong>Meta poġġejna domna nistennew nofs siegħa sakemm ġie l-wejter jagħtina l-menus, u dam tliet kwarti oħra biex jieħu l-ordni.</strong></p><p>After we sat down we waited half an hour before the waiter came to give us the menus, and then he took another three quarters of an hour to take the order.</p><ul><li><strong>meta</strong> when</li><li><strong>poġġejna</strong> we sat down</li><li><strong>domna</strong> we took (time)</li><li><strong>nistennew</strong> waiting</li><li><strong>nofs siegħa</strong> half an hour</li><li><strong>sakemm</strong> until</li><li><strong>ġie</strong> he came</li><li><strong>il-wejter</strong> the waiter</li><li><strong>jagħtina</strong> gives us</li><li><strong>il-menus</strong> the menus (plural)</li><li><strong>u</strong> and</li><li><strong>dam</strong> he took</li><li><strong>tliet kwarti oħra</strong> another three quarters</li><li><strong>biex</strong> to / before</li><li><strong>jieħu</strong> he takes</li><li><strong>l-ordni</strong> the order.</li></ul></blockquote><blockquote><p><strong>Agħar minn hekk, meta l-ordni waslet kienet ħażina u minfuq ried ir-raġun il-wejter!</strong></p><p>Worse still, when the order arrived it was wrong, and what&#39;s more the waiter insisted he was right!</p><ul><li><strong>agħar</strong> worse</li><li><strong>minn hekk</strong> than that</li><li><strong>meta</strong> when</li><li><strong>waslet</strong> it arrived (feminine, the order)</li><li><strong>kienet ħażina</strong> it was wrong</li><li><strong>u</strong> and</li><li><strong>minfuq</strong> what&#39;s more</li><li><strong>ried</strong> he insisted/wanted</li><li><strong>ir-raġun</strong> being right</li><li><strong>il-wejter</strong> the waiter.</li></ul></blockquote><h3 id="the-two-replies" tabindex="-1">The Two Replies <a class="header-anchor" href="#the-two-replies" aria-label="Permalink to &quot;The Two Replies&quot;">​</a></h3><table><thead><tr><th>Original</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Mario: Ma naqbilx miegħek, meta morna hemm dejjem ħriġna sodisfatti. Kellimtu lill-maniġer? Kont tirranġa xi ħaġa żgur!</td><td>Mario: I don&#39;t agree with you; whenever we went there we always left satisfied. Did you talk to the manager? You could surely have sorted something out!<br><strong>ma naqbilx</strong> I don&#39;t agree<br><strong>miegħek</strong> with you<br><strong>meta morna</strong> when we went<br><strong>hemm</strong> there<br><strong>dejjem</strong> always<br><strong>ħriġna</strong> we left<br><strong>sodisfatti</strong> satisfied<br><strong>kellimtu</strong> did you talk to him<br><strong>lill-maniġer</strong> to the manager<br><strong>kont tirranġa</strong> you could have sorted<br><strong>xi ħaġa</strong> something<br><strong>żgur</strong> surely.</td></tr><tr><td>Ritianne: Kieku jien kont inqum u nitlaq meta nara li l-wejter għadu ma ġabx il-menus!</td><td>Ritianne: If it were me, I&#39;d have got up and left when I saw the waiter still hadn&#39;t brought the menus!<br><strong>kieku jien</strong> if it were me<br><strong>kont</strong> I would have<br><strong>inqum</strong> get up<br><strong>u</strong> and<br><strong>nitlaq</strong> leave<br><strong>meta</strong> when<br><strong>nara</strong> I see<br><strong>li</strong> that<br><strong>għadu</strong> still<br><strong>ma ġabx</strong> hadn&#39;t brought<br><strong>il-menus</strong> the menus.</td></tr></tbody></table><hr><h2 id="_5-writing-a-complaint" tabindex="-1">5 Writing a Complaint <a class="header-anchor" href="#_5-writing-a-complaint" aria-label="Permalink to &quot;5 Writing a Complaint&quot;">​</a></h2><p><strong>Il-kitba ta’ lment</strong> = writing a complaint.</p><ul><li><strong>kitba</strong> writing</li><li><strong>ta’</strong> of</li><li><strong>ilment</strong> complaint.</li></ul><h3 id="a-fill-in-complaint-model" tabindex="-1">A. Fill-in Complaint Model <a class="header-anchor" href="#a-fill-in-complaint-model" aria-label="Permalink to &quot;A. Fill-in Complaint Model&quot;">​</a></h3><p>Word bank for the exercise:</p><ul><li><strong>nistenna</strong> I wait</li><li><strong>iddiżappuntata</strong> disappointed, feminine</li><li><strong>nirrapporta</strong> I report</li><li><strong>teknixin</strong> technician</li><li><strong>friġġ</strong> fridge.</li></ul><table><thead><tr><th>Completed sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Ninsab iddiżappuntata bil-prodotti li xtrajt mingħand &quot;Lino tal-Appliances&quot;.</td><td>I am disappointed with the products I bought from &quot;Lino tal-Appliances&quot;.<br><strong>ninsab</strong> I am (in a state)<br><strong>iddiżappuntata</strong> disappointed (female speaker)<br><strong>bil-prodotti</strong> with the products<br><strong>li</strong> that<br><strong>xtrajt</strong> I bought<br><strong>mingħand</strong> from.</td></tr><tr><td>Wara biss xahrejn, il-friġġ bdiet tissaddad u l-magna tal-ħasil mhix taħdem sew.</td><td>After only two months, the fridge began to rust and the washing machine doesn&#39;t work properly.<br><strong>wara</strong> after<br><strong>biss</strong> only<br><strong>xahrejn</strong> two months<br><strong>il-friġġ</strong> the fridge<br><strong>bdiet</strong> began (feminine form)<br><strong>tissaddad</strong> rust<br><strong>u</strong> and<br><strong>il-magna tal-ħasil</strong> the washing machine<br><strong>mhix taħdem sew</strong> doesn&#39;t work properly.<br>The gender agreement in the original sentence appears inconsistent; understood as in the material.</td></tr><tr><td>Meta ċempilt biex nirrapporta, qaluli li rrid nistenna xahar biex jiġi t-teknixin.</td><td>When I called to report it, they told me I&#39;d have to wait a month for the technician to come.<br><strong>meta</strong> when<br><strong>ċempilt</strong> I called<br><strong>biex</strong> to<br><strong>nirrapporta</strong> I report<br><strong>qaluli</strong> they told me<br><strong>li</strong> that<br><strong>rrid</strong> I must<br><strong>nistenna</strong> wait<br><strong>xahar</strong> a month<br><strong>biex jiġi</strong> for him to come<br><strong>it-teknixin</strong> the technician.</td></tr><tr><td>Jien ma nistax nagħmel xahar bla magna tal-ħasil!</td><td>I can&#39;t go a month without a washing machine!<br><strong>jien</strong> I<br><strong>ma nistax</strong> I can&#39;t<br><strong>nagħmel</strong> go/do<br><strong>xahar</strong> a month<br><strong>bla</strong> without<br><strong>magna tal-ħasil</strong> washing machine.</td></tr></tbody></table><h3 id="b-complaint-letter-sentence-frames" tabindex="-1">B. Complaint Letter Sentence Frames <a class="header-anchor" href="#b-complaint-letter-sentence-frames" aria-label="Permalink to &quot;B. Complaint Letter Sentence Frames&quot;">​</a></h3><p><strong>Kompli dawn is-sentenzi biex tagħqad din l-ittra ta’ lment.</strong> (Continue these sentences to complete this complaint letter.)</p><table><thead><tr><th>Maltese</th><th>English</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>Sur Cachia,</td><td>Mr Cachia,</td><td><strong>Sur</strong> Mr<br><strong>Cachia</strong> a surname.</td></tr><tr><td>Ilbieraħ użajt is-servizz tal-kumpanija tiegħek &quot;Ħassiela tad-djar&quot;.</td><td>Yesterday I used your company&#39;s &quot;Home Cleaning&quot; service.</td><td><strong>ilbieraħ</strong> yesterday<br><strong>użajt</strong> I used<br><strong>is-servizz</strong> the service<br><strong>tal-kumpanija</strong> of the company<br><strong>tiegħek</strong> your<br><strong>Ħassiela tad-djar</strong> home cleaning company name.</td></tr><tr><td>Jiddispjaċini ngħidlek dan għaliex …</td><td>I&#39;m sorry to tell you this because …</td><td><strong>jiddispjaċini</strong> I&#39;m sorry<br><strong>ngħidlek</strong> tell you<br><strong>dan</strong> this<br><strong>għaliex</strong> because.</td></tr><tr><td>Nixtieq li …</td><td>I would like …</td><td><strong>nixtieq</strong> I would like<br><strong>li</strong> that (introduces the clause).</td></tr><tr><td>Nispera li taċċetta.</td><td>I hope you accept.</td><td><strong>nispera</strong> I hope<br><strong>li</strong> that<br><strong>taċċetta</strong> you accept.</td></tr><tr><td>Saħħiet, Is-Sinjura Fenech</td><td>Regards, Mrs Fenech</td><td><strong>saħħiet</strong> regards/cheers<br><strong>is-Sinjura</strong> Mrs<br><strong>Fenech</strong> a surname.</td></tr></tbody></table><h3 id="b-complete-model-answer" tabindex="-1">B. Complete Model Answer <a class="header-anchor" href="#b-complete-model-answer" aria-label="Permalink to &quot;B. Complete Model Answer&quot;">​</a></h3><blockquote><p>Sur Cachia,</p><p>Ilbieraħ użajt is-servizz tal-kumpanija tiegħek &quot;Ħassiela tad-djar&quot;. Jiddispjaċini ngħidlek li ma kontx sodisfatta, dan għaliex l-art baqgħet maħmuġa u t-twieqi ma tnaddfux sew.</p><p>Nixtieq li tibgħat lil xi ħadd biex jerġa’ jnaddaf id-dar.</p><p>Nispera li taċċetta l-ilment tiegħi u li ssolvi din il-problema.</p><p>Saħħiet,</p><p>Is-Sinjura Fenech</p></blockquote><p>Breakdown of the newly added parts:</p><table><thead><tr><th>Added part</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>li ma kontx sodisfatta</td><td>that I was not satisfied.<br><strong>li</strong> introduces the clause<br><strong>ma kontx</strong> I was not<br><strong>sodisfatta</strong> satisfied (feminine).</td></tr><tr><td>l-art baqgħet maħmuġa u t-twieqi ma tnaddfux sew</td><td>the floor stayed dirty and the windows weren&#39;t cleaned properly.<br><strong>l-art</strong> the floor<br><strong>baqgħet</strong> stayed (feminine)<br><strong>maħmuġa</strong> dirty<br><strong>u</strong> and<br><strong>t-twieqi</strong> the windows<br><strong>ma tnaddfux</strong> weren&#39;t cleaned<br><strong>sew</strong> properly.</td></tr><tr><td>tibgħat lil xi ħadd biex jerġa’ jnaddaf id-dar</td><td>send someone to clean the house again.<br><strong>tibgħat</strong> you send<br><strong>lil xi ħadd</strong> someone (object)<br><strong>biex</strong> to<br><strong>jerġa’</strong> again<br><strong>jnaddaf</strong> clean<br><strong>id-dar</strong> the house.</td></tr><tr><td>l-ilment tiegħi u li ssolvi din il-problema</td><td>my complaint and that you solve this problem.<br><strong>l-ilment</strong> the complaint<br><strong>tiegħi</strong> my<br><strong>u</strong> and<br><strong>li</strong> introduces the clause<br><strong>ssolvi</strong> you solve<br><strong>din</strong> this (feminine)<br><strong>il-problema</strong> the problem.</td></tr></tbody></table><h3 id="c-free-writing" tabindex="-1">C. Free Writing <a class="header-anchor" href="#c-free-writing" aria-label="Permalink to &quot;C. Free Writing&quot;">​</a></h3><p><strong>Agħżel servizz jew prodott u ikteb ilment dwaru.</strong> Choose a service or product and write a complaint about it.</p><ul><li><strong>agħżel</strong> choose</li><li><strong>servizz</strong> service</li><li><strong>jew</strong> or</li><li><strong>prodott</strong> product</li><li><strong>u</strong> and</li><li><strong>ikteb</strong> write</li><li><strong>ilment</strong> complaint</li><li><strong>dwaru</strong> about it.</li></ul><h3 id="c-model-complaint-and-sentence-by-sentence-analysis" tabindex="-1">C. Model Complaint and Sentence-by-Sentence Analysis <a class="header-anchor" href="#c-model-complaint-and-sentence-by-sentence-analysis" aria-label="Permalink to &quot;C. Model Complaint and Sentence-by-Sentence Analysis&quot;">​</a></h3><blockquote><p>Għażiż Maniġer,</p><p>Ilbieraħ xtrajt mowbajl mill-ħanut tiegħek. Meta wasalt id-dar, indunajt li l-iskrin ma kienx jaħdem. Nixtieq mowbajl ieħor jew il-flus lura. Nispera li ssolvi din il-problema malajr.</p><p>Grazzi, Alex</p></blockquote><table><thead><tr><th>Sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>Għażiż Maniġer</td><td>Dear Manager.<br><strong>għażiż</strong> dear<br><strong>maniġer</strong> manager.</td></tr><tr><td>Ilbieraħ xtrajt mowbajl mill-ħanut tiegħek.</td><td>Yesterday I bought a phone from your shop.<br><strong>ilbieraħ</strong> yesterday<br><strong>xtrajt</strong> I bought<br><strong>mowbajl</strong> mobile phone<br><strong>mill-ħanut</strong> from the shop<br><strong>tiegħek</strong> your.</td></tr><tr><td>Meta wasalt id-dar, indunajt li l-iskrin ma kienx jaħdem.</td><td>When I got home, I noticed the screen didn&#39;t work.<br><strong>meta</strong> when<br><strong>wasalt</strong> I arrived<br><strong>id-dar</strong> home<br><strong>indunajt</strong> I noticed<br><strong>li</strong> that<br><strong>l-iskrin</strong> the screen<br><strong>ma kienx</strong> it wasn&#39;t<br><strong>jaħdem</strong> working.</td></tr><tr><td>Nixtieq mowbajl ieħor jew il-flus lura.</td><td>I&#39;d like another phone or my money back.<br><strong>nixtieq</strong> I&#39;d like<br><strong>mowbajl</strong> phone<br><strong>ieħor</strong> another<br><strong>jew</strong> or<br><strong>il-flus</strong> the money<br><strong>lura</strong> back.</td></tr><tr><td>Nispera li ssolvi din il-problema malajr.</td><td>I hope you solve this problem soon.<br><strong>nispera</strong> I hope<br><strong>li</strong> that<br><strong>ssolvi</strong> you solve<br><strong>din il-problema</strong> this problem<br><strong>malajr</strong> quickly.</td></tr><tr><td>Grazzi, Alex</td><td>Thanks, Alex.<br><strong>grazzi</strong> thanks<br><strong>Alex</strong> signature.</td></tr></tbody></table><hr><h2 id="_6-singular-and-plural-word-table" tabindex="-1">6 Singular and Plural Word Table <a class="header-anchor" href="#_6-singular-and-plural-word-table" aria-label="Permalink to &quot;6 Singular and Plural Word Table&quot;">​</a></h2><p><strong>Is-Singular u l-Plural. Kompli din it-tabella.</strong> (Singular and plural; complete this table.) The entries and their common correspondences follow; the blanks are completed with the plural forms found elsewhere in the book:</p><table><thead><tr><th>Singular</th><th>Plural</th><th>English</th></tr></thead><tbody><tr><td>xogħol</td><td>xogħlijiet</td><td>work, jobs</td></tr><tr><td>siegħa</td><td>sigħat</td><td>hour</td></tr><tr><td>karozza</td><td>karozzi</td><td>car</td></tr><tr><td>ħaddiem</td><td>ħaddiema</td><td>worker</td></tr><tr><td>vann</td><td>vannijiet</td><td>van</td></tr><tr><td>servizz</td><td>servizzi</td><td>service</td></tr><tr><td>restorant</td><td>restorants</td><td>restaurant</td></tr><tr><td>wejter</td><td>wejters</td><td>waiter</td></tr><tr><td>maniġer</td><td>maniġers</td><td>manager</td></tr><tr><td>menu</td><td>menus</td><td>menu</td></tr><tr><td>ċurkett</td><td>ċrieket</td><td>ring</td></tr><tr><td>ħanut</td><td>ħwienet</td><td>shop</td></tr><tr><td>suba’</td><td>swaba’</td><td>finger (subgħ- appears in possessive etc. forms)</td></tr><tr><td>libsa</td><td>ilbiesi</td><td>dress</td></tr><tr><td>pjazza</td><td>pjazez</td><td>square</td></tr><tr><td>xahar</td><td>xhur</td><td>month</td></tr></tbody></table><p><strong>Word prompts:</strong></p><ul><li><em>singular</em> = singular</li><li><em>plural</em> = plural</li><li><em>kompli</em> = continue/complete</li><li><em>din it-tabella</em> = this table.</li></ul><hr><h2 id="_7-regular-full-plurals" tabindex="-1">7 Regular/Full Plurals <a class="header-anchor" href="#_7-regular-full-plurals" aria-label="Permalink to &quot;7 Regular/Full Plurals&quot;">​</a></h2><p><strong>Plural Sħiħ — Żieda ta’ suffiss mal-kelma. Adding a suffix to the word.</strong></p><p>&quot;Full plurals&quot; are usually formed by adding an ending to the stem. This page reproduces the original table; the arrow points from singular to plural. Some words also change spelling or stem, so it is best to memorise them as groups.</p><table><thead><tr><th>Singular → Plural</th><th>English</th></tr></thead><tbody><tr><td>Malti → Maltin</td><td>Maltese (man/generic)</td></tr><tr><td>Għawdxi → Għawdxin</td><td>Gozitan</td></tr><tr><td>Baħri → baħrin</td><td>sailor</td></tr><tr><td>Barri → barrin</td><td>bull</td></tr><tr><td>Qaddis → qaddisin</td><td>saint</td></tr><tr><td>Ħalliel → ħallelin</td><td>thief</td></tr><tr><td>Għażżien → għażżenin</td><td>lazy person</td></tr><tr><td>Għajjien → għajjenin</td><td>tired person</td></tr><tr><td>Ħaddiem → ħaddiema</td><td>worker</td></tr><tr><td>Għalliem → għalliema</td><td>teacher</td></tr><tr><td>Sajjied → sajjieda</td><td>fisherman</td></tr><tr><td>Karozza → karozzi</td><td>car</td></tr><tr><td>Ferrovija → ferroviji</td><td>train</td></tr><tr><td>Ajruplan → ajruplani</td><td>aeroplane</td></tr><tr><td>Biljett → biljetti</td><td>ticket</td></tr><tr><td>Mowbajl → mowbajls</td><td>mobile phone</td></tr><tr><td>Kompjuter → kompjuters</td><td>computer</td></tr><tr><td>Wejter → wejters</td><td>waiter</td></tr><tr><td>Restorant → restorants</td><td>restaurant</td></tr><tr><td>Għatu → għotjien</td><td>lid</td></tr><tr><td>Qiegħ → qigħan</td><td>bottom</td></tr><tr><td>Triq → triqat</td><td>road (spelling as in the textbook)</td></tr><tr><td>Xemgħa → xemgħat</td><td>candle</td></tr><tr><td>Tebgħa → tebgħat</td><td>stain</td></tr><tr><td>Demgħa → demgħat</td><td>tear</td></tr><tr><td>Ġimgħa → ġimgħat</td><td>week</td></tr><tr><td>Wied → widien</td><td>valley</td></tr><tr><td>Bieb → bibien</td><td>door</td></tr><tr><td>Sid → sidien</td><td>owner</td></tr><tr><td>Għar → għerien</td><td>cave</td></tr><tr><td>Dnub → dnubiet</td><td>sin, fault</td></tr><tr><td>Tfajla → tfajliet</td><td>girl</td></tr><tr><td>Omm → ommijiet</td><td>mother</td></tr><tr><td>Missier → missirijiet</td><td>father</td></tr><tr><td>Vann → vannijiet</td><td>van</td></tr><tr><td>Xogħol → xogħlijiet</td><td>work, jobs</td></tr></tbody></table><p><strong>Reading the instruction word by word:</strong></p><ul><li><em>Żieda</em> addition</li><li><em>ta’</em> of</li><li><em>suffiss</em> suffix</li><li><em>mal-kelma</em> to the word.</li></ul><p>Example: <strong>karozza</strong> (car) → <strong>karozzi</strong> (cars).</p><hr><h2 id="_8-write-the-plurals-from-pictures-1" tabindex="-1">8 Write the Plurals from Pictures (1) <a class="header-anchor" href="#_8-write-the-plurals-from-pictures-1" aria-label="Permalink to &quot;8 Write the Plurals from Pictures (1)&quot;">​</a></h2><p><strong>Imla l-vojt billi tagħti l-kelma skont l-istampa u fil-ġenb ikteb jekk hux plural sħiħ jew miksur.</strong></p><p>Fill in the blanks by giving the word for the picture, and write beside it whether it is a full or broken plural.</p><ul><li><strong>imla l-vojt</strong> fill in the blank</li><li><strong>billi</strong> by</li><li><strong>tagħti</strong> give</li><li><strong>il-kelma</strong> the word</li><li><strong>skont</strong> according to</li><li><strong>l-istampa</strong> the picture</li><li><strong>fil-ġenb</strong> at the side</li><li><strong>ikteb</strong> write</li><li><strong>jekk hux</strong> whether it is</li><li><strong>sħiħ</strong> full</li><li><strong>jew</strong> or</li><li><strong>miksur</strong> broken.</li></ul><table><thead><tr><th>Picture</th><th>Singular → Plural</th><th>Type</th></tr></thead><tbody><tr><td>one ball → several balls</td><td>ballun → blalen</td><td>broken plural: internal vowel/stem change. Given as the example in the textbook.</td></tr><tr><td>one button → several buttons</td><td>buttuna → buttuni</td><td>full plural (common regular ending).</td></tr><tr><td>one table → several tables</td><td>mejda → imwejjed</td><td>broken plural.</td></tr><tr><td>one cup/glass → several cups/glasses</td><td>tazza → tazzi</td><td>full plural.</td></tr><tr><td>one sock → several socks</td><td>kalzetta → kalzetti</td><td>full plural.</td></tr></tbody></table><hr><h2 id="_9-write-the-plurals-from-pictures-2" tabindex="-1">9 Write the Plurals from Pictures (2) <a class="header-anchor" href="#_9-write-the-plurals-from-pictures-2" aria-label="Permalink to &quot;9 Write the Plurals from Pictures (2)&quot;">​</a></h2><p>This page continues the table and instruction from page 8; the pictures are a motorbike, a pencil, a dog, a cat, and a bucket.</p><p>Word by word:</p><ul><li><strong>singular</strong> singular</li><li><strong>plural</strong> plural.</li></ul><table><thead><tr><th>Picture</th><th>Singular → Plural</th><th>Type</th></tr></thead><tbody><tr><td>motorbike</td><td>mutur → muturi</td><td>full plural</td></tr><tr><td>pencil</td><td>lapes → lapsijiet</td><td>full plural (-ijiet ending)</td></tr><tr><td>dog</td><td>kelb → klieb</td><td>broken plural</td></tr><tr><td>cat</td><td>qattus → qtates</td><td>broken plural</td></tr><tr><td>bucket</td><td>barmil → bramel</td><td>broken plural</td></tr></tbody></table><hr><h2 id="_10-write-the-plurals-from-pictures-3" tabindex="-1">10 Write the Plurals from Pictures (3) <a class="header-anchor" href="#_10-write-the-plurals-from-pictures-3" aria-label="Permalink to &quot;10 Write the Plurals from Pictures (3)&quot;">​</a></h2><p>This page&#39;s pictures are one boy/several children, one phone/several phones, one bed/several beds, one umbrella/several umbrellas.</p><table><thead><tr><th>Picture</th><th>Singular → Plural</th><th>Type</th></tr></thead><tbody><tr><td>boy → children</td><td>tifel → tfal</td><td>broken plural</td></tr><tr><td>phone</td><td>mowbajl → mowbajls</td><td>full plural</td></tr><tr><td>bed</td><td>sodda → sodod</td><td>broken plural</td></tr><tr><td>umbrella</td><td>umbrella → umbrelel</td><td>broken plural (common plural for loanwords)</td></tr></tbody></table><hr><h2 id="_11-plural-nouns-in-sentences" tabindex="-1">11 Plural Nouns in Sentences <a class="header-anchor" href="#_11-plural-nouns-in-sentences" aria-label="Permalink to &quot;11 Plural Nouns in Sentences&quot;">​</a></h2><p><strong>It-taħriġ dwar in-nomi u l-għadd.</strong> (The exercise about nouns and number.)</p><ul><li><strong>taħriġ</strong> exercise</li><li><strong>dwar</strong> about</li><li><strong>in-nomi</strong> nouns</li><li><strong>l-għadd</strong> number/count.</li></ul><p>The exercise asks you to underline the plural nouns, then write their singular and mark <strong>s</strong> (full plural) or <strong>m</strong> (broken plural).</p><table><thead><tr><th>Original sentence</th><th>English</th><th>Plural noun analysis</th></tr></thead><tbody><tr><td>Iż-żeffiena tal-grupp ħarġu tajjeb ħafna imma nistqarr li s-saħħa tal-grupp tinsab fil-kantanti.</td><td>The group&#39;s dancers performed very well, but I admit the strength of the group lies in the singers.</td><td><strong>iż-żeffiena</strong> the dancers (plural, singular <em>żeffien</em>)<br><strong>il-kantanti</strong> the singers (plural, singular <em>kantant</em>).<br><strong>grupp</strong> group<br><strong>saħħa</strong> strength<br><strong>tajjeb</strong> well are not plural nouns.</td></tr><tr><td>Il-bajjiet Maltin sbieħ imma l-ibħra tal-madwar sfortunatament ma tantx jinżammu nodfa.</td><td>The Maltese beaches are beautiful, but unfortunately the surrounding seas are not kept very clean.</td><td><strong>il-bajjiet</strong> the beaches (singular <em>bajja</em>)<br><strong>l-ibħra</strong> the seas (singular <em>baħar</em>).<br><strong>Maltin</strong> Maltese, an adjective<br><strong>sbieħ/nodfa</strong> beautiful/clean are adjectives.</td></tr><tr><td>Il-molol tas-sodod ġodda tajbin ħafna.</td><td>The springs of the new beds are very good.</td><td><strong>il-molol</strong> the springs (singular <em>molla</em>)<br><strong>is-sodod</strong> the beds (singular <em>sodda</em>)<br><strong>ġodda</strong> new<br><strong>tajbin</strong> good are plural adjectives.</td></tr><tr><td>Id-djar tagħhom huma kbar. Għandhom ħafna garaxxijiet u kollha kbar.</td><td>Their houses are big. They have many garages and they are all big.</td><td><strong>id-djar</strong> the houses (singular <em>dar</em>)<br><strong>garaxxijiet</strong> garages (singular <em>garaxx</em>).<br><strong>kbar</strong> big<br><strong>kollha</strong> all are plural forms, but the exercise looks for nouns.</td></tr><tr><td>Tassew rajt annimali sbieħ fil-foresti li żort. Imma l-aktar annimali li laqtuni kienu l-iljunfanti.</td><td>I really saw beautiful animals in the forests I visited. But the animals that struck me most were the elephants.</td><td><strong>annimali</strong> animals (plural, singular <em>annimal</em>, appears twice)<br><strong>il-foresti</strong> the forests (singular <em>foresta</em>)<br><strong>l-iljunfanti</strong> the elephants (singular <em>iljunfant</em>).<br>There are four plural noun occurrences in the sentence; the exercise table has only 11 rows, possibly related to the textbook layout/scoring.</td></tr></tbody></table><p><strong>Part B table headers:</strong></p><ul><li><em>In-nom il-plural</em> the plural noun</li><li><em>Plural sħiħ / Plural miksur</em> full/broken plural</li><li><em>In-nom fis-singular</em> the singular noun.</li></ul><p>Example: <strong>żeffiena → żeffien</strong>, marked <strong>s</strong>.</p><h3 id="a-full-analysis-of-the-remaining-words-in-the-sentences" tabindex="-1">A. Full Analysis of the Remaining Words in the Sentences <a class="header-anchor" href="#a-full-analysis-of-the-remaining-words-in-the-sentences" aria-label="Permalink to &quot;A. Full Analysis of the Remaining Words in the Sentences&quot;">​</a></h3><table><thead><tr><th>Sentence no.</th><th>Additional word/phrase breakdown</th></tr></thead><tbody><tr><td>1</td><td><strong>tal-grupp</strong> of the group<br><strong>ħarġu</strong> they came out/performed<br><strong>tajjeb</strong> well<br><strong>ħafna</strong> very<br><strong>imma</strong> but<br><strong>nistqarr</strong> I admit<br><strong>li</strong> that<br><strong>s-saħħa</strong> the strength<br><strong>tal-grupp</strong> of the group<br><strong>tinsab</strong> lies in<br><strong>fil-kantanti</strong> in the singers.</td></tr><tr><td>2</td><td><strong>Maltin</strong> Maltese (plural adjective)<br><strong>sbieħ</strong> beautiful (plural)<br><strong>imma</strong> but<br><strong>tal-madwar</strong> of the surroundings<br><strong>sfortunatament</strong> unfortunately<br><strong>ma tantx</strong> not really<br><strong>jinżammu</strong> are kept<br><strong>nodfa</strong> clean (plural).</td></tr><tr><td>3</td><td><strong>tas-sodod</strong> of the beds<br><strong>ġodda</strong> new (plural; can modify the beds or the springs by context)<br><strong>tajbin</strong> good (plural)<br><strong>ħafna</strong> very.<br>In the translation &quot;mattresses&quot; is a contextual rendering; the original word sodod directly means &quot;beds&quot;.</td></tr><tr><td>4</td><td><strong>tagħhom</strong> their<br><strong>huma</strong> are<br><strong>kbar</strong> big (plural)<br><strong>għandhom</strong> they have<br><strong>ħafna</strong> many<br><strong>u</strong> and<br><strong>kollha</strong> all<br><strong>kbar</strong> big.</td></tr><tr><td>5</td><td><strong>tassew</strong> really<br><strong>rajt</strong> I saw<br><strong>sbieħ</strong> beautiful (plural)<br><strong>fil-foresti</strong> in the forests<br><strong>li</strong> that<br><strong>żort</strong> I visited<br><strong>imma</strong> but<br><strong>l-aktar</strong> most<br><strong>annimali</strong> animals<br><strong>li</strong> that<br><strong>laqtuni</strong> they struck me<br><strong>kienu</strong> they were<br><strong>l-iljunfanti</strong> the elephants.</td></tr></tbody></table><h3 id="b-full-classification-and-singular-answers" tabindex="-1">B. Full Classification and Singular Answers <a class="header-anchor" href="#b-full-classification-and-singular-answers" aria-label="Permalink to &quot;B. Full Classification and Singular Answers&quot;">​</a></h3><p>Listed without duplicates, 11 items; <code>annimali</code> appears twice in sentence 5 but is recorded once here.</p><table><thead><tr><th>Plural noun</th><th>s / m</th><th>Singular</th><th>English</th></tr></thead><tbody><tr><td>żeffiena</td><td>s</td><td>żeffien</td><td>dancer; given as the example in the textbook</td></tr><tr><td>kantanti</td><td>s</td><td>kantant</td><td>singer</td></tr><tr><td>bajjiet</td><td>s</td><td>bajja</td><td>bay/beach</td></tr><tr><td>ibħra</td><td>m</td><td>baħar</td><td>sea</td></tr><tr><td>molol</td><td>m</td><td>molla</td><td>spring</td></tr><tr><td>sodod</td><td>m</td><td>sodda</td><td>bed</td></tr><tr><td>djar</td><td>m</td><td>dar</td><td>house</td></tr><tr><td>garaxxijiet</td><td>s</td><td>garaxx</td><td>garage</td></tr><tr><td>annimali</td><td>s</td><td>annimal</td><td>animal</td></tr><tr><td>foresti</td><td>s</td><td>foresta</td><td>forest</td></tr><tr><td>iljunfanti</td><td>s</td><td>iljunfant</td><td>elephant</td></tr></tbody></table><ul><li><strong>aqta’ linja taħt</strong> draw a line under.</li><li><strong>in-nomi fis-sentenzi</strong> the nouns in the sentences.</li><li><strong>li qegħdin fil-plural</strong> that are in the plural.</li><li><strong>ikteb il-kliem</strong> write the words.</li><li><strong>li qtajt linja taħtu</strong> that you underlined.</li><li><strong>immarka</strong> mark.</li><li><strong>jekk huwiex</strong> whether it is.</li><li><strong>fil-plural sħiħ</strong> full plural.</li><li><strong>jew fil-plural miksur</strong> or broken plural.</li><li><strong>u ikteb</strong> and write.</li><li><strong>is-singular tiegħu</strong> its singular.</li></ul><hr><h2 id="_12-prepositions-of-place-1" tabindex="-1">12 Prepositions of Place (1) <a class="header-anchor" href="#_12-prepositions-of-place-1" aria-label="Permalink to &quot;12 Prepositions of Place (1)&quot;">​</a></h2><p><strong>Il-Prepożizzjonijiet: Fejn qiegħed dan it-tifel?</strong> (Prepositions: where is this boy?)</p><ul><li><strong>prepożizzjonijiet</strong> prepositions</li><li><strong>fejn</strong> where</li><li><strong>qiegħed</strong> located</li><li><strong>dan it-tifel</strong> this boy.</li></ul><table><thead><tr><th>Preposition</th><th>English</th></tr></thead><tbody><tr><td>taħt</td><td>under</td></tr><tr><td>fuq</td><td>on, above</td></tr><tr><td>quddiem</td><td>in front of</td></tr><tr><td>ħdejn / maġenb</td><td>next to</td></tr><tr><td>fuq in-naħa tax-xellug</td><td>on the left side</td></tr><tr><td>fuq in-naħa tal-lemin</td><td>on the right side</td></tr><tr><td>wara</td><td>behind</td></tr><tr><td>bejn</td><td>between</td></tr></tbody></table><p>According to the pictures, fill in the blanks; the answers are ordered as follows (the exercise is laid out in two columns):</p><ol><li><strong>It-tifel qiegħed quddiem il-kaxxa.</strong> The boy is in front of the box.<br><strong>it-tifel</strong> the boy<br><strong>qiegħed</strong> located<br><strong>quddiem</strong> in front of<br><strong>il-kaxxa</strong> the box.</li><li><strong>It-tifel qiegħed wara l-kaxxa.</strong> The boy is behind the box.</li><li><strong>It-tifel jinsab fuq il-kaxxa.</strong> The boy is on top of the box.<br><strong>jinsab</strong> is located.</li><li><strong>It-tifel jinsab taħt il-mejda.</strong> The boy is under the table.<br><strong>il-mejda</strong> the table.</li><li><strong>It-tifel qiegħed bejn il-kaxxi.</strong> The boy is between the boxes.<br><strong>il-kaxxi</strong> the boxes (plural).</li><li><strong>It-tifel qiegħed ħdejn il-kaxxa.</strong> The boy is next to the box.</li><li><strong>It-tifel qiegħed fuq in-naħa tax-xellug tal-kaxxa.</strong> The boy is on the left side of the box.<br><strong>in-naħa</strong> the side<br><strong>tax-xellug</strong> of the left<br><strong>tal-kaxxa</strong> of the box.</li><li><strong>It-tifel qiegħed fuq in-naħa tal-lemin tal-kaxxa.</strong> The boy is on the right side of the box.<br><strong>tal-lemin</strong> of the right.</li></ol><hr><h2 id="_13-the-apple-and-the-box" tabindex="-1">13 The Apple and the Box <a class="header-anchor" href="#_13-the-apple-and-the-box" aria-label="Permalink to &quot;13 The Apple and the Box&quot;">​</a></h2><p><strong>Fejn qiegħda t-tuffieħa?</strong> Where is the apple?</p><ul><li><strong>fejn</strong> where</li><li><strong>qiegħda</strong> located (feminine)</li><li><strong>it-tuffieħa</strong> the apple.</li></ul><h3 id="position-description-picture-by-picture" tabindex="-1">Position Description Picture by Picture <a class="header-anchor" href="#position-description-picture-by-picture" aria-label="Permalink to &quot;Position Description Picture by Picture&quot;">​</a></h3><p>There are 9 small pictures, numbered <strong>from top to bottom, left to right within each row</strong>. Left/right is from the reader&#39;s viewpoint; front/back is judged mainly by whether the apple covers the box or is covered by it. The expressions below are reference answers based on the pictures, not answers provided by the textbook.</p><table><thead><tr><th>No. and position</th><th>Description</th><th>Maltese reference sentence</th><th>Word-by-word breakdown</th></tr></thead><tbody><tr><td>1: first row, left</td><td>The apple is on top of the box.</td><td><strong>It-tuffieħa qiegħda fuq il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located (feminine singular)<br><strong>fuq</strong> on (page 12)<br><strong>il-kaxxa</strong> the box.</td></tr><tr><td>2: first row, middle</td><td>The box is open and the apple is inside it.</td><td><strong>It-tuffieħa qiegħda fil-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>fil-kaxxa</strong> in the box (fi + il-kaxxa; extra expression on this page).</td></tr><tr><td>3: first row, right</td><td>The apple is on the right side of the box, close beside it.</td><td><strong>It-tuffieħa qiegħda fuq in-naħa tal-lemin tal-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>fuq in-naħa tal-lemin</strong> on the right side (page 12)<br><strong>tal-kaxxa</strong> of the box.</td></tr><tr><td>4: second row, left</td><td>The apple is in front of the box, slightly to the left of the frame, covering part of the box&#39;s front.</td><td><strong>It-tuffieħa qiegħda quddiem il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>quddiem</strong> in front of (page 12)<br><strong>il-kaxxa</strong> the box.</td></tr><tr><td>5: second row, middle</td><td>The apple is behind the box, slightly to the right, partly hidden by it.</td><td><strong>It-tuffieħa qiegħda wara l-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>wara</strong> behind (page 12)<br><strong>il-kaxxa</strong> the box.</td></tr><tr><td>6: second row, right</td><td>The apple is between two boxes.</td><td><strong>It-tuffieħa qiegħda bejn il-kaxxi.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>bejn</strong> between (page 12)<br><strong>il-kaxxi</strong> the boxes (plural; two boxes in the picture).</td></tr><tr><td>7: third row, left</td><td>The box is placed diagonally above the apple; the apple is under the box.</td><td><strong>It-tuffieħa qiegħda taħt il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>taħt</strong> under (page 12)<br><strong>il-kaxxa</strong> the box.</td></tr><tr><td>8: third row, middle</td><td>The apple is upside down, drawn inside the open box; tentatively described as &quot;inside&quot;, the box-in/out relation needs checking against the original picture.</td><td><strong>It-tuffieħa qiegħda fil-kaxxa.</strong> (provisional)</td><td><strong>it-tuffieħa</strong> the apple<br><strong>qiegħda</strong> located<br><strong>fil-kaxxa</strong> in the box (tentative reading; not &quot;under&quot; just because the apple is upside down).</td></tr><tr><td>9: third row, right</td><td>Several apples are distributed around one box, not one apple between two boxes.</td><td><strong>It-tuffieħ qiegħed madwar il-kaxxa.</strong></td><td><strong>it-tuffieħ</strong> apples (collective noun for the several apples in the picture)<br><strong>qiegħed</strong> located (agreeing with collective tuffieħ)<br><strong>madwar</strong> around (extra expression on this page)<br><strong>il-kaxxa</strong> the box.</td></tr></tbody></table><h3 id="correspondence-with-the-page-12-vocabulary" tabindex="-1">Correspondence with the Page 12 Vocabulary <a class="header-anchor" href="#correspondence-with-the-page-12-vocabulary" aria-label="Permalink to &quot;Correspondence with the Page 12 Vocabulary&quot;">​</a></h3><ul><li><strong>fuq</strong> on: picture 1.</li><li><strong>taħt</strong> under: picture 7.</li><li><strong>quddiem</strong> in front of: picture 4.</li><li><strong>wara</strong> behind: picture 5; the difference from picture 3 is that the apple is partly hidden by the box.</li><li><strong>bejn</strong> between: picture 6; the plural <strong>il-kaxxi</strong> is used because the reference objects are two boxes.</li><li><strong>ħdejn / maġenb</strong> next to: picture 3 could also be <strong>It-tuffieħa qiegħda ħdejn il-kaxxa.</strong>, but that doesn&#39;t say left or right.</li><li><strong>fuq in-naħa tal-lemin</strong> on the right side: the more specific expression for picture 3. The whole phrase means &quot;on the right side&quot;; don&#39;t translate only the <strong>fuq</strong> in it as &quot;above&quot;.</li><li><strong>fuq in-naħa tax-xellug</strong> on the left side: picture 4 is also somewhat left in the frame, so one could add <strong>It-tuffieħa qiegħda fuq in-naħa tax-xellug tal-kaxxa.</strong>; however, since it covers the front of the box, <strong>quddiem</strong> is the more accurate main relation.</li><li><strong>fil-kaxxa</strong> in the box: picture 2, and provisionally picture 8; not &quot;on top of the box&quot;.</li><li><strong>madwar</strong> around: picture 9; distinct from <strong>bejn</strong> (between two or more reference objects).</li></ul><p><strong>Still to check:</strong> the box boundaries and the apple overlap in picture 8 are unclear; &quot;inside&quot; is not treated as the only certain answer. Picture 9 uses the collective noun <strong>tuffieħ</strong> rather than the single apple <strong>tuffieħa</strong>, so <strong>qiegħed</strong> is used accordingly.</p><hr><h2 id="_14-prepositions-of-place-2" tabindex="-1">14 Prepositions of Place (2) <a class="header-anchor" href="#_14-prepositions-of-place-2" aria-label="Permalink to &quot;14 Prepositions of Place (2)&quot;">​</a></h2><p><strong>Imla l-vojt billi tuża l-prepożizzjonijiet skont l-istampa.</strong> Fill in the blanks using the prepositions according to the picture.</p><ul><li><strong>tuża</strong> use</li><li><strong>skont l-istampa</strong> according to the picture.</li></ul><table><thead><tr><th>Sentence</th><th>Translation and word-by-word breakdown</th></tr></thead><tbody><tr><td>1. Is-siġġu qiegħed ħdejn il-mejda.</td><td>The chair is next to the table.<br><strong>is-siġġu</strong> the chair<br><strong>qiegħed</strong> located<br><strong>ħdejn</strong> next to<br><strong>il-mejda</strong> the table.<br>Already given.</td></tr><tr><td>2. Il-ballun jinsab taħt il-mejda.</td><td>The ball is under the table.<br><strong>il-ballun</strong> the ball<br><strong>jinsab</strong> is located<br><strong>taħt</strong> under.</td></tr><tr><td>3. Il-mejda tinsab bejn is-siġġu u l-pultruna.</td><td>The table is between the chair and the armchair.<br><strong>tinsab</strong> is located (feminine)<br><strong>bejn</strong> between<br><strong>u</strong> and<br><strong>il-pultruna</strong> the armchair.</td></tr><tr><td>4. Fuq il-pultruna hemm żewġ kuxins.</td><td>There are two cushions on the armchair.<br><strong>fuq</strong> on<br><strong>il-pultruna</strong> the armchair<br><strong>hemm</strong> there are<br><strong>żewġ</strong> two<br><strong>kuxins</strong> cushions.<br>The original item reads &quot;____ fil-pultruna hemm...&quot;; this sentence changes fil-pultruna to il-pultruna, a natural-usage rewrite, not the original word-for-word fill-in.</td></tr><tr><td>5. Il-qattus qiegħed ħdejn il-pultruna.</td><td>The cat is next to the armchair.<br><strong>il-qattus</strong> the cat<br><strong>qiegħed</strong> located<br><strong>ħdejn</strong> next to<br><strong>il-pultruna</strong> the armchair.<br>The cat is to the right of the chair in the picture; ħdejn is clearer, though wara could be discussed by partial overlap, but it is not the only determinable relation.</td></tr><tr><td>6. Il-ktieb qiegħed fuq il-mejda u ħdejn il-lampa.</td><td>The book is on the table, next to the lamp.<br><strong>il-ktieb</strong> the book<br><strong>fuq</strong> on<br><strong>u</strong> and<br><strong>ħdejn</strong> next to<br><strong>il-lampa</strong> the lamp.</td></tr><tr><td>7. Il-vażun qiegħed ħdejn il-lampa.</td><td>The vase is next to the lamp.<br><strong>il-vażun</strong> the vase<br><strong>qiegħed</strong> located<br><strong>ħdejn</strong> next to.</td></tr><tr><td>8. Il-lampa qiegħda bejn il-ktieb u l-vażun.</td><td>The lamp is between the book and the vase.<br><strong>il-lampa</strong> the lamp<br><strong>qiegħda</strong> located (feminine)<br><strong>bejn</strong> between.</td></tr><tr><td>9. It-tapit qiegħed quddiem l-affarijiet.</td><td>The carpet is in front of the things.<br><strong>it-tapit</strong> the carpet<br><strong>quddiem</strong> in front of<br><strong>l-affarijiet</strong> the things (plural).</td></tr><tr><td>10. L-arloġġ qiegħed fuq l-affarijiet.</td><td>The clock is above/on top of the things.<br><strong>l-arloġġ</strong> the clock<br><strong>fuq</strong> on<br><strong>l-affarijiet</strong> the things.</td></tr></tbody></table><p>For items 9 and 10, &quot;the things&quot; refers to the whole group of furniture in the picture; when using <em>quddiem</em> (in front of) or <em>fuq</em> (above), the point is to describe the relative position as in the picture.</p><hr><h2 id="_15-list-singular-nouns-from-the-picture-and-write-their-plurals" tabindex="-1">15 List Singular Nouns from the Picture and Write Their Plurals <a class="header-anchor" href="#_15-list-singular-nouns-from-the-picture-and-write-their-plurals" aria-label="Permalink to &quot;15 List Singular Nouns from the Picture and Write Their Plurals&quot;">​</a></h2><p><strong>Agħmel lista tan-nomi fis-singular li jidhru fl-istampa, imbagħad agħti l-plural tagħhom u għid hux sħiħ jew miksur.</strong></p><p>Make a list of the singular nouns that appear in the picture, then give their plurals and say whether each is full or broken.</p><ul><li><strong>agħmel lista</strong> make a list</li><li><strong>tan-nomi</strong> of the nouns</li><li><strong>fis-singular</strong> in the singular</li><li><strong>li jidhru</strong> that appear</li><li><strong>fl-istampa</strong> in the picture</li><li><strong>imbagħad</strong> then</li><li><strong>agħti</strong> give</li><li><strong>tagħhom</strong> their</li><li><strong>u għid</strong> and say</li><li><strong>hux</strong> whether it is</li><li><strong>sħiħ jew miksur</strong> full or broken.</li></ul><p>This page has a blank table; the picture it refers to should be the living-room illustration on the previous page. Possible examples from the picture:</p><table><thead><tr><th>Singular noun</th><th>Plural</th><th>Type</th></tr></thead><tbody><tr><td>siġġu (chair)</td><td>siġġijiet</td><td>full</td></tr><tr><td>mejda (table)</td><td>mwejjed</td><td>broken</td></tr><tr><td>ballun (ball)</td><td>blalen</td><td>broken</td></tr><tr><td>pultruna (armchair)</td><td>pultruni</td><td>full</td></tr><tr><td>kuxin (cushion)</td><td>kuxins</td><td>full</td></tr><tr><td>qattus (cat)</td><td>qtates</td><td>broken</td></tr><tr><td>ktieb (book)</td><td>kotba</td><td>broken</td></tr><tr><td>lampa (lamp)</td><td>lampi</td><td>full</td></tr><tr><td>vażun (vase)</td><td>vażuni</td><td>full</td></tr><tr><td>tapit (carpet)</td><td>twapet</td><td>broken</td></tr><tr><td>arloġġ (clock)</td><td>arloġġi</td><td>full</td></tr></tbody></table><h2 id="review-points" tabindex="-1">Review Points <a class="header-anchor" href="#review-points" aria-label="Permalink to &quot;Review Points&quot;">​</a></h2><ol><li><strong>Asking about and explaining a situation:</strong><br><em>X’ġralek?</em> (What happened to you?)<br><em>Ma nafx</em> (I don&#39;t know)<br><em>Skużani</em> (Sorry / excuse me).</li><li><strong>Asking for help and service:</strong><br><em>Xi ħadd jista’ jgħinni?</em> (Can someone help me?)<br><em>Nixtieq inkellem lill-maniġer</em> (I&#39;d like to speak to the manager).</li><li><strong>Expressing position:</strong><br><em>fuq</em> on<br><em>taħt</em> under<br><em>quddiem</em> in front of<br><em>wara</em> behind<br><em>bejn</em> between<br><em>ħdejn/maġenb</em> next to.</li><li><strong>Noun plurals:</strong> regular and broken plurals both need to be memorised with examples; don&#39;t assume every word just adds the same ending.</li></ol>',150),s=[a];function i(d,l,g,h,u,b){return r(),e("div",null,s)}const c=t(o,[["render",i]]);export{p as __pageData,c as default};
